package com.morongaming.forsakenrealm;
import android.graphics.*;import org.json.*;
final class CosmeticArt {
 static void draw(Canvas c,JSONObject a,float x,float y,Paint p){if(a==null)return;int color=0xffb6a16c;try{color=Color.parseColor(a.optString("color"));}catch(Exception ignored){}p.setShader(new RadialGradient(x+24,y+22,28,new int[]{color,0xff262722},null,Shader.TileMode.CLAMP));c.drawCircle(x+24,y+24,23,p);p.setShader(null);p.setColor(0xffe0d3ae);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2);String symbol=a.optString("symbol");Path shape=new Path();if(symbol.equals("companion")){c.drawOval(x+13,y+23,x+35,y+37,p);for(int i=0;i<3;i++)c.drawCircle(x+13+i*11,y+15,4,p);}else if(symbol.equals("gold")){c.drawCircle(x+24,y+24,15,p);c.drawLine(x+24,y+12,x+24,y+36,p);}else if(symbol.equals("crown")){shape.moveTo(x+8,y+15);shape.lineTo(x+14,y+35);shape.lineTo(x+34,y+35);shape.lineTo(x+40,y+15);shape.lineTo(x+29,y+24);shape.lineTo(x+24,y+10);shape.lineTo(x+19,y+24);shape.close();c.drawPath(shape,p);}else if(symbol.equals("blade")){c.drawLine(x+12,y+36,x+36,y+12,p);c.drawLine(x+9,y+25,x+23,y+39,p);c.drawLine(x+29,y+12,x+36,y+12,p);}else if(symbol.equals("shield")){shape.moveTo(x+10,y+12);shape.lineTo(x+38,y+12);shape.lineTo(x+35,y+30);shape.lineTo(x+24,y+40);shape.lineTo(x+13,y+30);shape.close();c.drawPath(shape,p);}else if(symbol.equals("leaf")||symbol.equals("flame")){shape.moveTo(x+24,y+8);shape.cubicTo(x+46,y+30,x+28,y+44,x+16,y+34);shape.cubicTo(x+5,y+22,x+20,y+22,x+24,y+8);c.drawPath(shape,p);c.drawLine(x+19,y+37,x+28,y+18,p);}else if(symbol.equals("raven")){shape.moveTo(x+7,y+15);shape.lineTo(x+24,y+28);shape.lineTo(x+41,y+15);shape.lineTo(x+32,y+33);shape.lineTo(x+24,y+39);shape.lineTo(x+16,y+33);shape.close();c.drawPath(shape,p);}else{for(int i=0;i<4;i++){double angle=i*Math.PI/4;float dx=(float)Math.cos(angle)*16,dy=(float)Math.sin(angle)*16;c.drawLine(x+24-dx,y+24-dy,x+24+dx,y+24+dy,p);}}p.setStyle(Paint.Style.FILL);}
}

